Given an array date[] = [d, m, y], where d denotes the day, m denotes the month, and y denotes the year, Write a program that calculates the day of the week for any particular date in the past or future.Examples:Input: d = 30, m = 8, y = 2010Output: 1Explanation: 30th August 2010 was a Monday.Input: d = 15, m = 6, y = 1995Output: 4Explanation: 15th June 1995 was a Thursday.Input: d = 29, m = 2, y = 2016Output: 1Explanation: 26th January was a Monday.Try It YourselfTable of Content[Naive Approach] Day Count Calculation - O(Y + M) Time and O(1) Space[Expected Approach] Zeller's Congruence Formula - O(1) Time and O(1) Space[Naive Approach] Day Count Calculation - O(Y + M) Time and O(1) SpaceCalculate total number of days from 01-01-0001 to given date. Since 01-01-0001 was Monday, map totalDays % 7 to day of week.Initialize totalDays = 0Add days of all complete years before given yearAdd days of all complete months before given monthAdd days of current month minus 1Use weekDays array starting with MondayReturn weekDays[totalDays % 7]
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool isLeapYear(int year) {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

string getDayOfWeek(vector<int>& date) {
    int day = date[0];
    int month = date[1];
    int year = date[2];

    vector<int> daysInMonth = {
        31,28,31,30,31,30,
        31,31,30,31,30,31
    };

    vector<string> weekDays = {
        "Monday","Tuesday","Wednesday",
        "Thursday","Friday","Saturday","Sunday"
    };

    long long totalDays = 0;

    // Count complete years before current year
    for (int y = 1; y < year; y++) {
        totalDays += isLeapYear(y) ? 366 : 365;
    }

    // Count complete months before current month
    for (int m = 1; m < month; m++) {
        if (m == 2 && isLeapYear(year))
            totalDays += 29;
        else
            totalDays += daysInMonth[m - 1];
    }

    // Add days in current month
    totalDays += day - 1;

    // 01-01-0001 was Monday
    return weekDays[totalDays % 7];
}

int main() {
    vector<int> date = {17, 4, 1435};

    cout << getDayOfWeek(date) << endl;

    return 0;
}


